export const SCHEMA_SQL = "-- Zephiel API — schema\r\n-- Idempotent: safe to run repeatedly (npm run db:migrate).\r\n\r\nCREATE EXTENSION IF NOT EXISTS pgcrypto;\r\n\r\n-- ---------------------------------------------------------------- catalog --\r\n\r\nCREATE TABLE IF NOT EXISTS categories (\r\n  id          uuid PRIMARY KEY DEFAULT gen_random_uuid(),\r\n  slug        text UNIQUE NOT NULL,\r\n  name        text NOT NULL,\r\n  blurb       text NOT NULL DEFAULT '',\r\n  icon        text NOT NULL DEFAULT '',\r\n  sort_order  integer NOT NULL DEFAULT 0,\r\n  created_at  timestamptz NOT NULL DEFAULT now()\r\n);\r\n\r\nCREATE TABLE IF NOT EXISTS apis (\r\n  id              uuid PRIMARY KEY DEFAULT gen_random_uuid(),\r\n  slug            text UNIQUE NOT NULL,\r\n  name            text NOT NULL,\r\n  tagline         text NOT NULL DEFAULT '',\r\n  description     text NOT NULL DEFAULT '',\r\n  category_id     uuid REFERENCES categories(id) ON DELETE SET NULL,\r\n  provider        text NOT NULL DEFAULT '',\r\n  logo            text NOT NULL DEFAULT '',\r\n  color           text NOT NULL DEFAULT '#2445d6',\r\n  rating          numeric(2,1) NOT NULL DEFAULT 5.0,\r\n  reviews         integer NOT NULL DEFAULT 0,\r\n  subscribers     integer NOT NULL DEFAULT 0,\r\n  latency         integer NOT NULL DEFAULT 100,\r\n  uptime          numeric(5,2) NOT NULL DEFAULT 99.9,\r\n  featured        boolean NOT NULL DEFAULT false,\r\n  free_tier       boolean NOT NULL DEFAULT true,\r\n  published       boolean NOT NULL DEFAULT true,\r\n  tags            text[] NOT NULL DEFAULT '{}',\r\n  use_cases       text[] NOT NULL DEFAULT '{}',\r\n  sample_response text NOT NULL DEFAULT '{}',\r\n  created_at      timestamptz NOT NULL DEFAULT now(),\r\n  updated_at      timestamptz NOT NULL DEFAULT now()\r\n);\r\n\r\nCREATE INDEX IF NOT EXISTS apis_category_idx  ON apis(category_id);\r\nCREATE INDEX IF NOT EXISTS apis_published_idx ON apis(published);\r\n\r\nCREATE TABLE IF NOT EXISTS plans (\r\n  id          uuid PRIMARY KEY DEFAULT gen_random_uuid(),\r\n  api_id      uuid NOT NULL REFERENCES apis(id) ON DELETE CASCADE,\r\n  name        text NOT NULL,\r\n  price       numeric(10,2) NOT NULL DEFAULT 0,\r\n  unit        text,\r\n  requests    text NOT NULL DEFAULT '',\r\n  rate_limit  text NOT NULL DEFAULT '',\r\n  features    text[] NOT NULL DEFAULT '{}',\r\n  popular     boolean NOT NULL DEFAULT false,\r\n  quota       integer NOT NULL DEFAULT 100,\r\n  sort_order  integer NOT NULL DEFAULT 0\r\n);\r\n\r\nCREATE INDEX IF NOT EXISTS plans_api_idx ON plans(api_id);\r\n\r\nCREATE TABLE IF NOT EXISTS endpoints (\r\n  id          uuid PRIMARY KEY DEFAULT gen_random_uuid(),\r\n  api_id      uuid NOT NULL REFERENCES apis(id) ON DELETE CASCADE,\r\n  method      text NOT NULL DEFAULT 'GET',\r\n  path        text NOT NULL,\r\n  summary     text NOT NULL DEFAULT '',\r\n  sort_order  integer NOT NULL DEFAULT 0\r\n);\r\n\r\nCREATE INDEX IF NOT EXISTS endpoints_api_idx ON endpoints(api_id);\r\n\r\n-- ------------------------------------------------------ accounts & access --\r\n\r\nCREATE TABLE IF NOT EXISTS users (\r\n  id            uuid PRIMARY KEY DEFAULT gen_random_uuid(),\r\n  email         text UNIQUE NOT NULL,\r\n  name          text NOT NULL DEFAULT '',\r\n  password_hash text NOT NULL,\r\n  role          text NOT NULL DEFAULT 'customer' CHECK (role IN ('admin','customer')),\r\n  created_at    timestamptz NOT NULL DEFAULT now()\r\n);\r\n\r\nCREATE TABLE IF NOT EXISTS sessions (\r\n  id         text PRIMARY KEY,\r\n  user_id    uuid NOT NULL REFERENCES users(id) ON DELETE CASCADE,\r\n  expires_at timestamptz NOT NULL,\r\n  created_at timestamptz NOT NULL DEFAULT now()\r\n);\r\n\r\nCREATE INDEX IF NOT EXISTS sessions_user_idx ON sessions(user_id);\r\n\r\nCREATE TABLE IF NOT EXISTS api_keys (\r\n  id           uuid PRIMARY KEY DEFAULT gen_random_uuid(),\r\n  user_id      uuid NOT NULL REFERENCES users(id) ON DELETE CASCADE,\r\n  label        text NOT NULL DEFAULT 'Default',\r\n  scope        text NOT NULL DEFAULT 'All APIs',\r\n  key_prefix   text NOT NULL,\r\n  key_hash     text UNIQUE NOT NULL,\r\n  last_used_at timestamptz,\r\n  revoked_at   timestamptz,\r\n  created_at   timestamptz NOT NULL DEFAULT now()\r\n);\r\n\r\nCREATE INDEX IF NOT EXISTS api_keys_user_idx ON api_keys(user_id);\r\nCREATE INDEX IF NOT EXISTS api_keys_hash_idx ON api_keys(key_hash);\r\n\r\n-- ------------------------------------------------ subscriptions & billing --\r\n\r\nCREATE TABLE IF NOT EXISTS subscriptions (\r\n  id                 uuid PRIMARY KEY DEFAULT gen_random_uuid(),\r\n  user_id            uuid NOT NULL REFERENCES users(id) ON DELETE CASCADE,\r\n  api_id             uuid NOT NULL REFERENCES apis(id) ON DELETE CASCADE,\r\n  plan_id            uuid NOT NULL REFERENCES plans(id) ON DELETE CASCADE,\r\n  status             text NOT NULL DEFAULT 'pending'\r\n                     CHECK (status IN ('active','pending','cancelled','expired')),\r\n  quota              integer NOT NULL DEFAULT 100,\r\n  used               integer NOT NULL DEFAULT 0,\r\n  -- Billable units for per-unit plans (e.g. number of connected stores).\r\n  units              integer NOT NULL DEFAULT 1,\r\n  current_period_end timestamptz,\r\n  created_at         timestamptz NOT NULL DEFAULT now(),\r\n  updated_at         timestamptz NOT NULL DEFAULT now(),\r\n  UNIQUE (user_id, api_id)\r\n);\r\n\r\nCREATE INDEX IF NOT EXISTS subscriptions_user_idx ON subscriptions(user_id);\r\n\r\nCREATE TABLE IF NOT EXISTS payments (\r\n  id              uuid PRIMARY KEY DEFAULT gen_random_uuid(),\r\n  user_id         uuid REFERENCES users(id) ON DELETE SET NULL,\r\n  subscription_id uuid REFERENCES subscriptions(id) ON DELETE SET NULL,\r\n  reference       text UNIQUE NOT NULL,\r\n  amount          numeric(12,2) NOT NULL DEFAULT 0,\r\n  currency        text NOT NULL DEFAULT 'NGN',\r\n  status          text NOT NULL DEFAULT 'pending',\r\n  channel         text,\r\n  raw             jsonb,\r\n  created_at      timestamptz NOT NULL DEFAULT now(),\r\n  paid_at         timestamptz\r\n);\r\n\r\nCREATE INDEX IF NOT EXISTS payments_user_idx ON payments(user_id);\r\n\r\n-- ------------------------------------------------------------- metering --\r\n\r\nCREATE TABLE IF NOT EXISTS usage_events (\r\n  id         uuid PRIMARY KEY DEFAULT gen_random_uuid(),\r\n  user_id    uuid NOT NULL REFERENCES users(id) ON DELETE CASCADE,\r\n  api_id     uuid NOT NULL REFERENCES apis(id) ON DELETE CASCADE,\r\n  api_key_id uuid REFERENCES api_keys(id) ON DELETE SET NULL,\r\n  endpoint   text NOT NULL DEFAULT '/',\r\n  method     text NOT NULL DEFAULT 'GET',\r\n  status     integer NOT NULL DEFAULT 200,\r\n  latency_ms integer NOT NULL DEFAULT 0,\r\n  created_at timestamptz NOT NULL DEFAULT now()\r\n);\r\n\r\nCREATE INDEX IF NOT EXISTS usage_user_created_idx ON usage_events(user_id, created_at DESC);\r\nCREATE INDEX IF NOT EXISTS usage_api_idx          ON usage_events(api_id);\r\n\r\n-- ------------------------------------------------------------- settings --\r\n\r\n-- Runtime configuration editable from the admin console. Secret values are\r\n-- stored encrypted (see src/lib/settings.ts); non-secrets are plaintext.\r\nCREATE TABLE IF NOT EXISTS settings (\r\n  key        text PRIMARY KEY,\r\n  value      text NOT NULL DEFAULT '',\r\n  is_secret  boolean NOT NULL DEFAULT false,\r\n  updated_at timestamptz NOT NULL DEFAULT now(),\r\n  updated_by uuid REFERENCES users(id) ON DELETE SET NULL\r\n);\r\n\r\n-- Per-listing icon, stored as a key into the registry in src/lib/icons.ts.\r\n-- Falls back to the two-letter monogram when empty.\r\nALTER TABLE apis ADD COLUMN IF NOT EXISTS icon text NOT NULL DEFAULT '';\r\n\r\n-- --------------------------------------------------------------- stores --\r\n\r\n-- Connected storefronts under a per-unit subscription (the Multistore API).\r\n-- Each store carries its own API key so traffic can be attributed and a single\r\n-- store revoked without disturbing the others.\r\nCREATE TABLE IF NOT EXISTS stores (\r\n  id              uuid PRIMARY KEY DEFAULT gen_random_uuid(),\r\n  user_id         uuid NOT NULL REFERENCES users(id) ON DELETE CASCADE,\r\n  subscription_id uuid NOT NULL REFERENCES subscriptions(id) ON DELETE CASCADE,\r\n  name            text NOT NULL,\r\n  platform        text NOT NULL DEFAULT 'shopify',\r\n  status          text NOT NULL DEFAULT 'synced'\r\n                  CHECK (status IN ('synced','syncing','sandbox','error')),\r\n  created_at      timestamptz NOT NULL DEFAULT now()\r\n);\r\n\r\nCREATE INDEX IF NOT EXISTS stores_user_idx ON stores(user_id);\r\nCREATE INDEX IF NOT EXISTS stores_sub_idx  ON stores(subscription_id);\r\n\r\n-- A key may be scoped to one store; NULL means an account-wide key.\r\nALTER TABLE api_keys     ADD COLUMN IF NOT EXISTS store_id uuid REFERENCES stores(id) ON DELETE CASCADE;\r\nALTER TABLE usage_events ADD COLUMN IF NOT EXISTS store_id uuid REFERENCES stores(id) ON DELETE SET NULL;\r\n\r\nCREATE INDEX IF NOT EXISTS usage_store_created_idx ON usage_events(store_id, created_at DESC);\r\n\r\n-- Optional storefront URL — the only identifier a custom/headless store has.\r\nALTER TABLE stores ADD COLUMN IF NOT EXISTS domain text NOT NULL DEFAULT '';\r\n\r\n-- --------------------------------------------------------- notifications --\r\n\r\n-- Outbound emails we have sent about a subscription. The unique constraint is\r\n-- the deduplication: one reminder of each kind per billing period, however\r\n-- many times the sweep runs.\r\nCREATE TABLE IF NOT EXISTS notifications (\r\n  id              uuid PRIMARY KEY DEFAULT gen_random_uuid(),\r\n  user_id         uuid NOT NULL REFERENCES users(id) ON DELETE CASCADE,\r\n  subscription_id uuid REFERENCES subscriptions(id) ON DELETE CASCADE,\r\n  kind            text NOT NULL,\r\n  period_end      timestamptz,\r\n  status          text NOT NULL DEFAULT 'sent',\r\n  detail          text NOT NULL DEFAULT '',\r\n  created_at      timestamptz NOT NULL DEFAULT now()\r\n);\r\n\r\nCREATE UNIQUE INDEX IF NOT EXISTS notifications_once_idx\r\n  ON notifications(subscription_id, kind, period_end);\r\n\r\nCREATE INDEX IF NOT EXISTS notifications_user_idx ON notifications(user_id, created_at DESC);\r\n\r\n-- --------------------------------------------------------- usage rollups --\r\n\r\n-- Historical call volume, one row per user/api/store/day.\r\n--\r\n-- usage_events is the hot table — every individual call, kept for the recent\r\n-- window that intraday charts need. Anything older is summarised here, because\r\n-- storing millions of rows to draw a daily line is wasteful and slow.\r\nCREATE TABLE IF NOT EXISTS usage_daily (\r\n  user_id    uuid NOT NULL REFERENCES users(id) ON DELETE CASCADE,\r\n  api_id     uuid NOT NULL REFERENCES apis(id) ON DELETE CASCADE,\r\n  store_id   uuid REFERENCES stores(id) ON DELETE CASCADE,\r\n  day        date NOT NULL,\r\n  calls      bigint NOT NULL DEFAULT 0,\r\n  errors     bigint NOT NULL DEFAULT 0,\r\n  avg_latency integer NOT NULL DEFAULT 0\r\n);\r\n\r\n-- store_id is nullable, so a composite primary key will not do: NULLs would\r\n-- never conflict. COALESCE to a sentinel gives one row per store-or-none.\r\nCREATE UNIQUE INDEX IF NOT EXISTS usage_daily_key_idx\r\n  ON usage_daily(user_id, api_id, day, COALESCE(store_id, '00000000-0000-0000-0000-000000000000'::uuid));\r\n\r\nCREATE INDEX IF NOT EXISTS usage_daily_user_day_idx ON usage_daily(user_id, day);\r\n\r\n-- Keep a demonstration account's charts alive: when set, the intraday window\r\n-- is topped up on read and the daily curve is extended by the rollup job.\r\nALTER TABLE subscriptions ADD COLUMN IF NOT EXISTS demo_traffic boolean NOT NULL DEFAULT false;\r\n\r\n-- --------------------------------------------------------------- reviews --\r\n\r\n-- One review per customer per API. Ratings shown on a listing are computed\r\n-- from these rows, so the distribution can never contradict the average.\r\nCREATE TABLE IF NOT EXISTS reviews (\r\n  id         uuid PRIMARY KEY DEFAULT gen_random_uuid(),\r\n  api_id     uuid NOT NULL REFERENCES apis(id) ON DELETE CASCADE,\r\n  user_id    uuid NOT NULL REFERENCES users(id) ON DELETE CASCADE,\r\n  rating     integer NOT NULL CHECK (rating BETWEEN 1 AND 5),\r\n  title      text NOT NULL DEFAULT '',\r\n  body       text NOT NULL DEFAULT '',\r\n  role       text NOT NULL DEFAULT '',\r\n  created_at timestamptz NOT NULL DEFAULT now(),\r\n  UNIQUE (api_id, user_id)\r\n);\r\n\r\nCREATE INDEX IF NOT EXISTS reviews_api_idx ON reviews(api_id, created_at DESC);\r\n\r\n-- -------------------------------------------------------- password resets --\r\n\r\n-- Only the digest is stored, so a leaked table cannot be used to reset anyone.\r\nCREATE TABLE IF NOT EXISTS password_resets (\r\n  token_hash text PRIMARY KEY,\r\n  user_id    uuid NOT NULL REFERENCES users(id) ON DELETE CASCADE,\r\n  expires_at timestamptz NOT NULL,\r\n  used_at    timestamptz,\r\n  created_at timestamptz NOT NULL DEFAULT now()\r\n);\r\n\r\nCREATE INDEX IF NOT EXISTS password_resets_user_idx ON password_resets(user_id);\r\n\r\n-- ----------------------------------------------------------------- posts --\r\n\r\nCREATE TABLE IF NOT EXISTS posts (\r\n  id           uuid PRIMARY KEY DEFAULT gen_random_uuid(),\r\n  slug         text UNIQUE NOT NULL,\r\n  title        text NOT NULL,\r\n  excerpt      text NOT NULL DEFAULT '',\r\n  body         text NOT NULL DEFAULT '',\r\n  tag          text NOT NULL DEFAULT 'Engineering',\r\n  read_minutes integer NOT NULL DEFAULT 5,\r\n  published    boolean NOT NULL DEFAULT true,\r\n  published_at timestamptz NOT NULL DEFAULT now(),\r\n  created_at   timestamptz NOT NULL DEFAULT now(),\r\n  updated_at   timestamptz NOT NULL DEFAULT now()\r\n);\r\n\r\nCREATE INDEX IF NOT EXISTS posts_published_idx ON posts(published, published_at DESC);\r\n\r\n-- ----------------------------------------------------------- subscribers --\r\n\r\nCREATE TABLE IF NOT EXISTS newsletter_subscribers (\r\n  id             uuid PRIMARY KEY DEFAULT gen_random_uuid(),\r\n  email          text UNIQUE NOT NULL,\r\n  source         text NOT NULL DEFAULT 'footer',\r\n  confirmed      boolean NOT NULL DEFAULT true,\r\n  unsubscribed_at timestamptz,\r\n  created_at     timestamptz NOT NULL DEFAULT now()\r\n);\r\n\r\n-- Reviews may be written by a customer (user_id set) or entered by an\r\n-- administrator on someone's behalf (author_name set). NULLs do not conflict\r\n-- in the unique index, so admin-entered rows are not limited to one per API.\r\nALTER TABLE reviews ALTER COLUMN user_id DROP NOT NULL;\r\nALTER TABLE reviews ADD COLUMN IF NOT EXISTS author_name text NOT NULL DEFAULT '';\r\n\r\n-- Plans are upserted by (api_id, name) rather than replaced, because\r\n-- subscriptions.plan_id cascades: deleting a plan deletes every subscription\r\n-- on it, and with it the customer's stores and per-store keys. Reseeding the\r\n-- catalogue must never do that.\r\nDELETE FROM plans p\r\n  USING plans q\r\n  WHERE p.api_id = q.api_id AND p.name = q.name AND p.id > q.id\r\n    AND NOT EXISTS (SELECT 1 FROM subscriptions s WHERE s.plan_id = p.id);\r\n\r\nCREATE UNIQUE INDEX IF NOT EXISTS plans_api_name_idx ON plans(api_id, name);\r\n\r\n-- Subscriptions can be billed monthly or annually; annual is charged for ten\r\n-- months. The column drives both the renewal period and what the invoice says.\r\nALTER TABLE subscriptions ADD COLUMN IF NOT EXISTS billing_interval text NOT NULL DEFAULT 'monthly';\r\n\r\nDO $$ BEGIN\r\n  ALTER TABLE subscriptions ADD CONSTRAINT subscriptions_billing_interval_check\r\n    CHECK (billing_interval IN ('monthly','annual'));\r\nEXCEPTION WHEN duplicate_object THEN NULL;\r\nEND $$;\r\n\r\n-- A pending payment carries the change it intends to make, so an upgrade does\r\n-- not touch the live subscription until the money actually clears. Previously\r\n-- starting a checkout flipped the subscription to 'pending' immediately, which\r\n-- revoked the customer's access before they had paid for anything.\r\nALTER TABLE payments ADD COLUMN IF NOT EXISTS plan_id uuid REFERENCES plans(id) ON DELETE SET NULL;\r\nALTER TABLE payments ADD COLUMN IF NOT EXISTS units integer NOT NULL DEFAULT 1;\r\nALTER TABLE payments ADD COLUMN IF NOT EXISTS billing_interval text NOT NULL DEFAULT 'monthly';\r\n\r\n-- Paystack refuses a second initialize on the same reference, so the checkout\r\n-- link is stored and reused. A customer who double-clicks Subscribe is sent\r\n-- back to the transaction they already started rather than charged twice.\r\nALTER TABLE payments ADD COLUMN IF NOT EXISTS authorization_url text;\r\n\r\nCREATE INDEX IF NOT EXISTS payments_pending_idx\r\n  ON payments(user_id, subscription_id, status) WHERE status = 'pending';\r\n\r\n-- Fixed-window counters for endpoints that are not the metered gateway.\r\n-- Kept in the database rather than in memory because serverless instances do\r\n-- not share state: an in-process counter would reset on every cold start and\r\n-- be enforced per instance rather than per account.\r\nCREATE TABLE IF NOT EXISTS rate_limits (\r\n  bucket       text PRIMARY KEY,\r\n  window_start timestamptz NOT NULL DEFAULT now(),\r\n  count        integer NOT NULL DEFAULT 0\r\n);\r\n\r\nCREATE INDEX IF NOT EXISTS rate_limits_window_idx ON rate_limits(window_start);\r\n\r\n-- Profile picture, stored in the row rather than an object store: the images\r\n-- are resized to a 256px square on upload, so they are a few kilobytes, and\r\n-- this avoids a second service to provision, authorise, and back up.\r\nALTER TABLE users ADD COLUMN IF NOT EXISTS avatar            bytea;\r\nALTER TABLE users ADD COLUMN IF NOT EXISTS avatar_type       text;\r\nALTER TABLE users ADD COLUMN IF NOT EXISTS avatar_updated_at timestamptz;\r\n\r\n-- Invoice identity for a payment. The number is drawn from a sequence so it is\r\n-- stable, ordered, and never reuses a value after a rolled-back transaction.\r\nCREATE SEQUENCE IF NOT EXISTS invoice_number_seq START 1001;\r\n\r\nALTER TABLE payments ADD COLUMN IF NOT EXISTS invoice_number  text UNIQUE;\r\nALTER TABLE payments ADD COLUMN IF NOT EXISTS receipt_sent_at timestamptz;\r\nALTER TABLE payments ADD COLUMN IF NOT EXISTS period_start    timestamptz;\r\nALTER TABLE payments ADD COLUMN IF NOT EXISTS period_end      timestamptz;\r\n\r\n-- The billing period start, stored rather than inferred.\r\n--\r\n-- It used to be derived as current_period_end minus one month, which is only\r\n-- right when every period is exactly a month. A backdated account whose first\r\n-- period runs from signup to a chosen renewal date could not be expressed, and\r\n-- usage reconciliation counted the wrong window for it.\r\nALTER TABLE subscriptions ADD COLUMN IF NOT EXISTS current_period_start timestamptz;\r\n\r\nUPDATE subscriptions SET current_period_start = current_period_end -\r\n  (CASE WHEN billing_interval = 'annual' THEN interval '1 year' ELSE interval '1 month' END)\r\nWHERE current_period_start IS NULL AND current_period_end IS NOT NULL;\r\n\r\n-- Admin-set usage baseline. `used` is reconciled as used_offset + real calls this period, so a value\r\n-- typed into the admin \"Calls used\" field sticks and future calls count up from it (offset may be\r\n-- negative to set a value below current real usage). Reset to 0 on renewal.\r\nALTER TABLE subscriptions ADD COLUMN IF NOT EXISTS used_offset integer NOT NULL DEFAULT 0;\r\n\r\n-- Where a call came from, and whether it is real.\r\n--\r\n-- The gateway recorded no caller identity, and generated demonstration traffic\r\n-- was written to the same table with nothing marking it apart, so there was no\r\n-- way to answer \"is this real traffic, and which application made it?\" from\r\n-- the data. `source` defaults to 'gateway' because every row written before\r\n-- this column existed came from the gateway.\r\nALTER TABLE usage_events ADD COLUMN IF NOT EXISTS origin     text;\r\nALTER TABLE usage_events ADD COLUMN IF NOT EXISTS user_agent text;\r\nALTER TABLE usage_events ADD COLUMN IF NOT EXISTS source     text NOT NULL DEFAULT 'gateway';\r\n\r\nCREATE INDEX IF NOT EXISTS usage_events_origin_idx\r\n  ON usage_events(user_id, origin, created_at DESC);\r\n\r\n-- Connected storefronts a plan allows. 0 means no fixed ceiling (Enterprise,\r\n-- which is negotiated). This used to be derived from whether the plan was\r\n-- free, so every paid tier shared one limit and the tiers could not differ.\r\nALTER TABLE plans ADD COLUMN IF NOT EXISTS store_limit integer NOT NULL DEFAULT 0;\r\n\r\n-- A storefront allowance granted to one account, overriding its plan's.\r\n-- Lets an operator extend a free trial by a store without moving the customer\r\n-- onto a paid plan or changing the plan for everyone on it.\r\nALTER TABLE subscriptions ADD COLUMN IF NOT EXISTS store_limit integer;\r\n\r\n-- --------------------------------------------------------- team members --\r\n\r\n-- A user may belong to another user's account as a MEMBER: they sign in with\r\n-- their own email + password, but share the owner's data (subscriptions,\r\n-- stores, API keys, usage, billing). account_owner_id is the owner's users.id;\r\n-- NULL means the user owns their own account. getCurrentUser() resolves the\r\n-- effective account id from this, so every query already scoped by user id\r\n-- keeps working — a member simply resolves to the owner's account.\r\nALTER TABLE users ADD COLUMN IF NOT EXISTS account_owner_id uuid REFERENCES users(id) ON DELETE CASCADE;\r\n\r\nCREATE INDEX IF NOT EXISTS users_account_owner_idx ON users(account_owner_id);\r\n";
